      "name": "greeting_and_identify",
      "node_type": "conversation",
      "on_enter": {
        "type": "tts",
        "text": "Hello, this is Freya Bank's digital assistant. This call is recorded. Am I speaking with {{title}} {{last_name}}?"
      },
      "on_enter_first_entry_only": false,
      "task_message": "Ask if you are speaking to {{title}} {{last_name}}. Only 'yes', the customer's full name, or clear equivalents confirm. If unclear, repeat the question once. For questions like 'who is this?', answer: You are Freya Bank's digital assistant. If not the customer, follow rules for relatives, wrong number, deceased, or to schedule callback. Never state the call reason or account unless identity is confirmed.",
      "extraction_schema": [
        {"name": "line_identity", "type": "string", "enum_values": ["customer_confirmed", "relative", "wrong_number", "deceased", "callback", "unclear"], "description": "Who is on the line after questioning", "min_confidence": 0.7},
        {"name": "callback_time", "type": "string", "description": "Requested callback time in HH:MM, empty if none", "min_confidence": 0.7}
      ],
      "max_node_turns": 5,
      "transitions": [
        { "target_node": "identity_check", "description": "Customer confirmed present", "condition": { "logic": "or", "conditions": [ { "variable": "line_identity", "operator": "equals", "operand": "customer_confirmed" } ] } },
        { "target_node": "handle_callback", "description": "Callback needed", "condition": { "logic": "or", "conditions": [ { "variable": "line_identity", "operator": "equals", "operand": "callback" } ] } },
        { "target_node": "close_wrong_number", "description": "Wrong number", "condition": { "logic": "or", "conditions": [ { "variable": "line_identity", "operator": "equals", "operand": "wrong_number" } ] } },
        { "target_node": "close_deceased", "description": "Deceased", "condition": { "logic": "or", "conditions": [ { "variable": "line_identity", "operator": "equals", "operand": "deceased" } ] } },
        { "target_node": "close_unclear", "description": "Identity unclear after 2 asks", "condition": { "logic": "or", "conditions": [ { "variable": "line_identity", "operator": "equals", "operand": "unclear" } ] } },
        { "target_node": "close_rel_break", "description": "Relative, no info given", "condition": { "logic": "or", "conditions": [ { "variable": "line_identity", "operator": "equals", "operand": "relative" } ] } },
        { "target_node": "greeting_and_identify", "description": "Still not clear, stay", "condition": { "operator": "always" } }
      ]
    },
    "handle_callback": {
      "name": "handle_callback",
      "node_type": "conversation",
      "task_message": "If callback_time is in allowed range (today or next business day, 10:00-19:00, after now), call schedule_callback. Otherwise, ask once for a valid time. If invalid again, do not schedule and close as no_callback.",
      "tools": [
        {
          "type": "function",
          "config": { "timeoutMs": 10000, "maxRetries": 0 },
          "function": {
            "name": "schedule_callback",
            "handler": "__function__:api_call",
            "parameters": {
              "type": "object",
              "properties": {
                "url": { "type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/schedule_callback" },
                "method": { "type": "string", "default": "POST" },
                "body": {
                  "type": "object",
                  "properties": {
                    "customer_id": { "type": "string", "default": "{{customer_id}}" },
                    "date": { "type": "string", "default": "{{callback_date}}" },
                    "time": { "type": "string", "default": "{{callback_time}}" }
                  },
                  "required": ["customer_id", "date", "time"]
                }
              }
            }
          },
          "description": "Book a callback if a valid date/time is provided."
        }
      ],
      "extraction_schema": [
        {"name": "callback_date", "type": "string", "description": "Callback date (YYYY-MM-DD)", "min_confidence": 0.7}
      ],
      "max_node_turns": 3,
      "transitions": [
        { "target_node": "close_callback", "description": "Callback scheduled", "condition": { "logic": "or", "conditions": [ { "variable": "schedule_callback_response.data.ok", "operator": "equals", "operand": "true" }, { "variable": "schedule_callback_response.data.ok", "operator": "equals", "operand": "True" } ] } },
        { "target_node": "close_no_callback", "description": "No valid callback possible after 2 asks", "condition": { "operator": "always" } }
      ]
    },
    "close_callback": {
      "name": "close_callback",
      "node_type": "end_call",
      "on_enter": { "type": "tts", "text": "Thank you. We will call back then. Goodbye." },
      "disable_inactivity_monitor": true,
      "transitions": [],
      "terminal": {
        "type": "function",
        "function": {
