{"file_path":"out/brief-a.workflow.json","content":"{
  "system_prompt": "You are Freya Bank's digital assistant on early-stage collections. Always speak truthfully, one or two clear sentences per turn. Follow every policy in the brief.",
  "initial_node": "greeting_and_identify",
  "test_variables": {
    "customer_id": "c_test",
    "first_name": "Dana",
    "last_name": "Smith",
    "title": "Ms",
    "now": "2026-10-14T11:00"
  },
  "nodes": {
    "greeting_and_identify": {
      "name": "greeting_and_identify",
      "node_type": "conversation",
      "on_enter": {"type": "tts", "text": "Hello, this is Freya Bank's digital assistant. This call is recorded. Am I speaking with {{title}} {{last_name}}?"},
      "on_enter_first_entry_only": false,
      "task_message": "Ask if you are speaking to {{title}} {{last_name}}. Only 'yes', the customer's name, or clear equivalents confirm. If unclear, repeat the question once. If they ask who you are, reply: You are Freya Bank's digital assistant. For a non-customer on the line (relative, wrong number, callback, deceased), route using extraction. Do not state call reason unless identity is confirmed.",
      "extraction_schema": [
        {"name": "line_identity", "type": "string", "enum_values": ["customer", "relative", "wrong_number", "deceased", "callback", "unclear"], "description": "Who is on the line", "min_confidence": 0.7},
        {"name": "callback_time", "type": "string", "description": "Requested callback time in HH:MM, empty if none", "min_confidence": 0.7}
      ],
      "max_node_turns": 5,
      "transitions": [
        {"target_node": "identity_check", "description": "Customer confirmed", "condition": {"logic": "or", "conditions": [{"variable": "line_identity", "operator": "equals", "operand": "customer"}]}},
        {"target_node": "handle_callback", "description": "Callback needed", "condition": {"logic": "or", "conditions": [{"variable": "line_identity", "operator": "equals", "operand": "callback"}]}},
        {"target_node": "close_wrong_number", "description": "Wrong number", "condition": {"logic": "or", "conditions": [{"variable": "line_identity", "operator": "equals", "operand": "wrong_number"}]}},
        {"target_node": "close_deceased", "description": "Deceased", "condition": {"logic": "or", "conditions": [{"variable": "line_identity", "operator": "equals", "operand": "deceased"}]}},
        {"target_node": "close_unclear", "description": "Identity unclear after 2 asks", "condition": {"logic": "or", "conditions": [{"variable": "line_identity", "operator": "equals", "operand": "unclear"}]}},
        {"target_node": "greeting_and_identify", "description": "Not clear, stay in node", "condition": {"operator": "always"}}
      ]
    },
    "handle_callback": {
      "name": "handle_callback",
      "node_type": "conversation",
      "task_message": "If callback_time in allowed range (today/next business day, 10:00-19:00, after now), call schedule_callback. Else ask once for another time, else close as no_callback.",
      "tools": [
        {"type": "function","config": {"timeoutMs": 10000, "maxRetries": 0},
        "function": {"name": "schedule_callback","handler": "__function__:api_call",
        "parameters": {"type": "object","properties": {"url": {"type": "string","default": "https://freya-bank-mock.freyavoice.workers.dev/v1/schedule_callback"},"method": {"type": "string","default": "POST"},"body": {"type": "object","properties": {"customer_id": {"type": "string","default": "{{customer_id}}"},"date": {"type": "string","default": "{{callback_date}}"},"time": {"type": "string","default": "{{callback_time}}"}},"required": ["customer_id","date","time"]}}}}}],
      "extraction_schema": [
        {"name": "callback_date", "type": "string", "description": "Callback date (YYYY-MM-DD)", "min_confidence": 0.7}
      ],
      "max_node_turns": 3,
      "transitions": [
        {"target_node": "close_callback", "description": "Callback scheduled", "condition": {"logic": "or", "conditions": [{"variable": "schedule_callback_response.data.ok", "operator": "equals", "operand": "true"},{"variable": "schedule_callback_response.data.ok", "operator": "equals", "operand": "True"}]}},
        {"target_node": "close_no_callback", "description": "No valid callback after 2 asks", "condition": {"operator": "always"}}
      ]
    },
    "close_callback": {
      "name": "close_callback",
      "node_type": "end_call",
      "on_enter": {"type": "tts", "text": "Thank you. We will call back then. Goodbye."},
      "disable_inactivity_monitor": true,
      "transitions": [],
      "terminal": {"type": "function","function": {"name": "close_call","handler": "__function__:api_call","parameters": {"type": "object","properties": {"url": {"type": "string","default": "https://freya-bank-mock.freyavoice.workers.dev/v1/close_call"},"method": "POST","body": {"type": "object","properties": {"customer_id": {"type": "string","default": "{{customer_id}}"},"outcome": {"type": "string","default": "not_reached"},"reason": {"type": "string","default": "callback"}}}}}}}
    },
    "close_no_callback": {
      "name": "close_no_callback",
      "node_type": "end_call",
      "on_enter": {"type": "tts", "text": "Sorry, could not schedule a callback. Goodbye."},
      "disable_inactivity_monitor": true,
      "transitions": [],
      "terminal": {"type": "function","function": {"name": "close_call","handler": "__function__:api_call","parameters": {"type": "object","properties": {"url": {"type": "string","default": "https://freya-bank-mock.freyavoice.workers.dev/v1/close_call"},"method": "POST","body": {"type": "object","properties": {"customer_id": {"type": "string","default": "{{customer_id}}"},"outcome": {"type": "string","default": "not_reached"},"reason": {"type": "string","default": "no_callback"}}}}}}}
    },
    "close_wrong_number": {
      "name": "close_wrong_number","node_type": "end_call","on_enter": {"type": "tts", "text": "Thank you. Goodbye."},"disable_inactivity_monitor": true,"transitions": [],"terminal": {"type": "function","function": {"name": "close_call","handler": "__function__:api_call","parameters": {"type": "object","properties": {"url": {"type": "string","default": "https://freya-bank-mock.freyavoice.workers.dev/v1/close_call"},"method": "POST","body": {"type": "object","properties": {"customer_id": {"type": "string","default": "{{customer_id}}"},"outcome": {"type": "string","default": "not_reached"},"reason": {"type": "string","default": "wrong_number"}}}}}}},
    "close_deceased": {
      "name": "close_deceased","node_type": "end_call","on_enter": {"type": "tts", "text": "I am sorry for your loss. Goodbye."},"disable_inactivity_monitor": true,"transitions": [],"terminal": {"type": "function","function": {"name": "close_call","handler": "__function__:api_call","parameters": {"type": "object","properties": {"url": {"type": "string","default": "https://freya-bank-mock.freyavoice.workers.dev/v1/close_call"},"method": "POST","body": {"type": "object","properties": {"customer_id": {"type": "string","default": "{{customer_id}}"},"outcome": {"type": "string","default": "not_reached"},"reason": {"type": "string","default": "deceased"}}}}}}},
    "close_unclear": {
      "name": "close_unclear","node_type": "end_call","on_enter": {"type": "tts", "text": "We could not confirm who is speaking. Goodbye."},"disable_inactivity_monitor": true,"transitions": [],"terminal": {"type": "function","function": {"name": "close_call","handler": "__function__:api_call","parameters": {"type": "object","properties": {"url": {"type": "string","default": "https://freya-bank-mock.freyavoice.workers.dev/v1/close_call"},"method": "POST","body": {"type": "object","properties": {"customer_id": {"type": "string","default": "{{customer_id}}"},"outcome": {"type": "string","default": "not_reached"},"reason": {"type": "string","default": "unclear"}}}}}}},
    "identity_check": {
      "name": "identity_check",
      "node_type": "conversation",
      "task_message": "Ask for date of birth in day-month-year order (as stated by the customer). If hint returned from previous try, ask for the month as a word. Call verify_identity with each answer. Up to three wrong total answers allowed, any question. If three wrong, close as failed; else, proceed to second question (last 4 digits of phone). On two refusals or no answer, close as declined. Do not leak any account/debt info unless all_verified.",
      "tools": [
        {"type": "function","config": {"timeoutMs": 10000, "maxRetries": 0},
        "function": {"name": "verify_identity", "handler": "__function__:api_call", "parameters": {"type": "object", "properties": {"url": {"type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/verify_identity"}, "method": {"type": "string", "default": "POST"}, "body": {"type": "object","properties": {"customer_id": {"type": "string","default": "{{customer_id}}"}, "field": {"type": "string","default": "{{field}}"}, "answer": {"type": "string","default": "{{answer}}"}},"required": ["customer_id","field", "answer"]}}}}, "description": "Check a security answer for dob or phone_last4."}
      ],
      "extraction_schema": [
        {"name": "identity_outcome", "type": "string", "enum_values": ["all_verified","failed","declined","retry","hint"], "description": "Identity check path", "min_confidence": 0.7}
      ],
      "max_node_turns": 10,
      "transitions": [
        {"target_node": "debt_statement", "description": "Both answers verified", "condition": {"logic": "or", "conditions": [{"variable": "verify_identity_response.data.all_verified","operator": "equals", "operand": "true"},{"variable": "verify_identity_response.data.all_verified","operator": "equals", "operand": "True"}]}},
        {"target_node": "close_id_failed", "description": "Three wrong answers", "condition": {"logic": "or", "conditions": [{"variable": "verify_identity_response.data.wrong_answers_left","operator": "equals", "operand": "0"}]}},
        {"target_node": "close_id_declined", "description": "Declined or refused to answer", "condition": {"logic": "or", "conditions": [{"variable": "identity_outcome","operator": "equals","operand": "declined"}]}},
        {"target_node": "identity_check", "description": "Retry or hint given", "condition": {"logic": "or", "conditions": [{"variable": "identity_outcome","operator": "equals","operand": "retry"},{"variable": "identity_outcome","operator": "equals","operand": "hint"}]}},
        {"target_node": "identity_check", "description": "Loop for input", "condition": {"operator": "always"}}
      ]
    },
    "close_id_failed": {
      "name": "close_id_failed","node_type": "end_call","on_enter": {"type": "tts", "text": "We could not verify your identity. Please use the bank app or visit a branch. Goodbye."},"disable_inactivity_monitor": true,"transitions": [],"terminal": {"type": "function","function": {"name": "close_call","handler": "__function__:api_call","parameters": {"type": "object","properties": {"url": {"type": "string","default": "https://freya-bank-mock.freyavoice.workers.dev/v1/close_call"},"method": "POST","body": {"type": "object","properties": {"customer_id": {"type": "string","default": "{{customer_id}}"},"outcome": {"type": "string","default": "not_verified"},"reason": {"type": "string","default": "failed"}}}}}}},
    "close_id_declined": {
      "name": "close_id_declined","node_type": "end_call","on_enter": {"type": "tts", "text": "We need those answers to protect your account. Goodbye."},"disable_inactivity_monitor": true,"transitions": [],"terminal": {"type": "function","function": {"name": "close_call","handler": "__function__:api_call","parameters": {"type": "object","properties": {"url": {"type": "string","default": "https://freya-bank-mock.freyavoice.workers.dev/v1/close_call"},"method": "POST","body": {"type": "object","properties": {"customer_id": {"type": "string","default": "{{customer_id}}"},"outcome": {"type": "string","default": "not_verified"},"reason": {"type": "string","default": "declined"}}}}}}},
    "debt_statement": {
      "name": "debt_statement",
      "node_type": "api_request",
      "passthrough": true,
      "passthrough_default_transition": "present_debt_statement",
      "on_enter": {"type": "silent"},
      "pre_actions": [
        {"type": "function","config": {"timeoutMs": 10000,"maxRetries": 1},
        "function": {"name": "get_account","handler": "__function__:api_call",
        "parameters": {"type": "object","properties": {"url": {"type": "string","default": "https://freya-bank-mock.freyavoice.workers.dev/v1/get_account"},"method": {"type": "string","default": "POST"},"body": {"type": "object","properties": {"customer_id": {"type": "string","default": "{{customer_id}}"}},"required": ["customer_id"]}}}}}
      ],
      "response_mapping": [{"path": "data.products","variable": "products"}],
      "transitions": [
        {"target_node": "present_debt_statement","description": "Account found","condition": {"operator": "always"}}
      ]
    },
    "present_debt_statement": {
      "name": "present_debt_statement","node_type": "conversation",
      "task_message": "Say you are calling from Freya Bank's collections team about a late payment. State the product in words ('credit card ending ...', 'personal loan', or 'car loan'), the past-due amount, and days late, using the result from get_account. Follow rules for language and accuracy. Then start the promise negotiation step.",
      "max_node_turns": 5,
      "transitions": [
        {"target_node": "collect_promise","description": "Stated debt, go to promise","condition": {"operator": "always"}}
      ]
    },
    "collect_promise": {
      "name": "collect_promise","node_type": "conversation",
      "task_message": "First ask: Can you make this payment today? Follow the rules for amount, deadline, attempts, and negotiation in the brief, including persuasions and explanations. If the customer accepts, move to confirm_promise. If refusal or non-answer, follow early/late band attempts. If hardship (sensitivity), route to transfer_support. If dispute or 'already paid', follow respective branches. Never promise what's not permitted by bank policy.",
      "extraction_schema": [{"name": "promise_intent","type": "string","enum_values": ["today","date_named","refusal","hardship","dispute","paid","reschedule","human","unclear"],"description": "Promise path chosen", "min_confidence": 0.7}],
      "max_node_turns": 10,
      "transitions": [
        {"target_node": "confirm_promise","description": "Customer ready to confirm promise","condition": {"logic": "or","conditions": [{"variable": "promise_intent","operator": "equals","operand": "today"},{"variable": "promise_intent","operator": "equals","operand": "date_named"}]}},
        {"target_node": "handle_hardship","description": "Hardship case","condition": {"variable": "promise_intent","operator": "equals","operand": "hardship"}},
        {"target_node": "handle_paid","description": "Already paid","condition": {"variable": "promise_intent","operator": "equals","operand": "paid"}},
        {"target_node": "handle_dispute","description": "Dispute","condition": {"variable": "promise_intent","operator": "equals","operand": "dispute"}},
        {"target_node": "handle_transfer","description": "Human requested or reschedule","condition": {"logic": "or","conditions": [{"variable": "promise_intent","operator": "equals","operand": "human"},{"variable": "promise_intent","operator": "equals","operand": "reschedule"}]}},
        {"target_node": "no_promise_refused","description": "Refusal or no answer","condition": {"variable": "promise_intent","operator": "equals","operand": "refusal"}},
        {"target_node": "collect_promise","description": "Loop for clarification or corrections","condition": {"operator": "always"}}
      ]
    },
    "confirm_promise": {
      "name": "confirm_promise","node_type": "conversation",
      "task_message": "Read the product, amount, and date back to the customer. Ask 'Do you confirm?'. Only call create_promise after a clear yes. If they change amount or date, loop to clarify and validate, then re-confirm.",
      "tools": [
        {"type": "function","config": {"timeoutMs": 10000, "maxRetries": 1},
        "function": {"name": "create_promise","handler": "__function__:api_call","parameters": {"type": "object","properties": {"url": {"type": "string","default": "https://freya-bank-mock.freyavoice.workers.dev/v1/create_promise"},"method": {"type": "string","default": "POST"},"body": {"type": "object","properties": {"customer_id": {"type": "string","default": "{{customer_id}}"},"product_id": {"type": "string","default": "{{products.0.product_id}}"},"amount": {"type": "number","default": "{{promise_amount}}"},"date": {"type": "string","default": "{{promise_date}}"}},"required": ["customer_id","product_id","amount","date"]}}}}}],
      "extraction_schema": [{"name": "promise_confirm_result","type": "string","enum_values": ["recorded","failed","correction","not_confirmed"],"description": "Promise confirmation result","min_confidence": 0.7}],
      "max_node_turns": 5,
      "transitions": [
        {"target_node": "success_promise_recorded","description": "Promise recorded","condition": {"logic": "or","conditions": [{"variable": "create_promise_response.data.ok","operator": "equals","operand": "true"},{"variable": "create_promise_response.data.ok","operator": "equals","operand": "True"}]}},
        {"target_node": "confirm_promise","description": "Customer corrects date/amount","condition": {"variable": "promise_confirm_result","operator": "equals","operand": "correction"}},
        {"target_node": "no_promise_service_error","description": "Failed after retries","condition": {"variable": "promise_confirm_result","operator": "equals","operand": "failed"}},
        {"target_node": "no_promise_refused","description": "Not confirmed","condition": {"variable": "promise_confirm_result","operator": "equals","operand": "not_confirmed"}},
        {"target_node": "confirm_promise","description": "Loop for input","condition": {"operator": "always"}}
      ]
    },
    "success_promise_recorded": {
      "name": "success_promise_recorded","node_type": "end_call","on_enter": {"type": "tts", "text": "Your payment promise is recorded. You will receive a text message confirming this promise. Thank you and goodbye."},"disable_inactivity_monitor": true,"transitions": [],"terminal": {"type": "function","function": {"name": "close_call","handler": "__function__:api_call","parameters": {"type": "object","properties": {"url": {"type": "string","default": "https://freya-bank-mock.freyavoice.workers.dev/v1/close_call"},"method": "POST","body": {"type": "object","properties": {"customer_id": {"type": "string","default": "{{customer_id}}"},"outcome": {"type": "string","default": "promise"}}}}}}},
    "no_promise_service_error": {"name": "no_promise_service_error","node_type": "end_call","on_enter": {"type": "tts", "text": "Sorry, we could not record your payment promise. Goodbye."},"disable_inactivity_monitor": true,"transitions": [],"terminal": {"type": "function","function": {"name": "close_call","handler": "__function__:api_call","parameters": {"type": "object","properties": {"url": {"type": "string","default": "https://freya-bank-mock.freyavoice.workers.dev/v1/close_call"},"method": "POST","body": {"type": "object","properties": {"customer_id": {"type": "string","default": "{{customer_id}}"},"outcome": {"type": "string","default": "no_promise"},"reason": {"type": "string","default": "service_error"}}}}}}},
