        "parameters": {"type": "object","properties": {"url": {"type": "string","default": "https://freya-bank-mock.freyavoice.workers.dev/v1/get_account"},"method": {"type": "string","default": "POST"},"body": {"type": "object","properties": {"customer_id": {"type": "string","default": "{{customer_id}}"}},"required": ["customer_id"]}}}}}
      ],
      "response_mapping": [{"path": "data.products","variable": "products"}],
