      "task_message": "Ask for date of birth in day-month-year order (as stated by the customer). If hint returned from previous try, ask for the month as a word. Call verify_identity with each answer. Up to three wrong total answers allowed, any question. If three wrong, close as failed; else, proceed to second question (last 4 digits of phone). On two refusals or no answer, close as declined. Do not leak any account/debt info unless all_verified.",
      "tools": [
        {"type": "function","config": {"timeoutMs": 10000, "maxRetries": 0},
        "function": {"name": "verify_identity", "handler": "__function__:api_call", "parameters": {"type": "object", "properties": {"url": {"type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/verify_identity"}, "method": {"type": "string", "default": "POST"}, "body": {"type": "object","properties": {"customer_id": {"type": "string","default": "{{customer_id}}"}, "field": {"type": "string","default": "{{field}}"}, "answer": {"type": "string","default": "{{answer}}"}},"required": ["customer_id","field", "answer"]}}}}, "description": "Check a security answer for dob or phone_last4."}
      ],
      "extraction_schema": [
        {"name": "identity_outcome", "type": "string", "enum_values": ["all_verified","failed","declined","retry","hint"], "description": "Identity check path", "min_confidence": 0.7}
      ],
      "max_node_turns": 10,
      "transitions": [
        {"target_node": "debt_statement", "description": "Both answers verified", "condition": {"logic": "or", "conditions": [{"variable": "verify_identity_response.data.all_verified","operator": "equals", "operand": "true"},{"variable": "verify_identity_response.data.all_verified","operator": "equals", "operand": "True"}]}},
        {"target_node": "close_id_failed", "description": "Three wrong answers", "condition": {"logic": "or", "conditions": [{"variable": "verify_identity_response.data.wrong_answers_left","operator": "equals", "operand": "0"}]}},
        {"target_node": "close_id_declined", "description": "Declined or refused to answer", "condition": {"logic": "or", "conditions": [{"variable": "identity_outcome","operator": "equals","operand": "declined"}]}},
        {"target_node": "identity_check", "description": "Retry or hint given", "condition": {"logic": "or", "conditions": [{"variable": "identity_outcome","operator": "equals","operand": "retry"},{"variable": "identity_outcome","operator": "equals","operand": "hint"}]}},
